 private GradientDrawable background(boolean focused){GradientDrawable d=new GradientDrawable();d.setColor(focused?0xFF354955:0xFF222E38);d.setCornerRadius(dp(6));if(focused)d.setStroke(dp(2),0xFFD2DFE5);return d;}
 private void style(View view){StateListDrawable d=new StateListDrawable();d.addState(new int[]{android.R.attr.state_focused},background(true));d.addState(new int[]{},background(false));view.setBackground(d);view.setFocusable(true);view.setId(View.generateViewId());}
 private Button button(String id,String label,Runnable run){Button b=new Button(activity);b.setAllCaps(false);b.setText(label);b.setTextColor(Color.WHITE);b.setTextSize(14);b.setPadding(dp(8),dp(3),dp(8),dp(3));style(b);actions.put(id,b);b.setOnClickListener(v->run.run());b.setOnFocusChangeListener((v,f)->{if(f)lastFocus=id;});return b;}
 static String modeName(String value){return value.equals("photo")?"Foto fija":value.equals("slideshow")?"Presentación":value.equals("daily")?"Paisaje diario":"Fondo original";}
 void show(){hide();visible=true;int token=epoch;if(focusedMode.isEmpty())focusedMode=prefs.getString("wallpaper_mode","original");if(lastFocus.isEmpty())lastFocus="mode:"+focusedMode;actions.clear();descriptions.clear();contextual.clear();contextActions.clear();
  LinearLayout root=new LinearLayout(activity);root.setOrientation(1);root.setBackgroundColor(0xFF121722);root.setPadding(dp(22),dp(14),dp(22),dp(12));LinearLayout header=new LinearLayout(activity);header.setGravity(Gravity.CENTER_VERTICAL);TextView title=text("Fondos del inicio",23);title.setTextColor(Color.WHITE);header.addView(title,new LinearLayout.LayoutParams(0,dp(35),1));activeLabel=text("",13);header.addView(activeLabel);root.addView(header);status=text("Solo en la pantalla de inicio",13);root.addView(status,new LinearLayout.LayoutParams(-1,dp(27)));
  LinearLayout body=new LinearLayout(activity);body.setOrientation(0);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));LinearLayout left=new LinearLayout(activity);left.setOrientation(1);LinearLayout.LayoutParams leftParams=new LinearLayout.LayoutParams(0,-1,4);leftParams.rightMargin=dp(16);body.addView(left,leftParams);imageFrame=new FrameLayout(activity);imageFrame.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xFF102E3A,0xFF121722,0xFF07090D}));image=new ImageView(activity);imageFrame.addView(image,new FrameLayout.LayoutParams(-1,-1));shade=new View(activity);shade.setBackgroundColor(0x65000000);shade.setVisibility(View.GONE);imageFrame.addView(shade,new FrameLayout.LayoutParams(-1,-1));left.addView(imageFrame,new LinearLayout.LayoutParams(-1,dp(205)));imageFrame.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{int height=Math.min((r-l)*9/16,Math.max(dp(100),left.getHeight()-dp(138)));if(height>0&&imageFrame.getLayoutParams().height!=height){imageFrame.getLayoutParams().height=height;imageFrame.requestLayout();}});caption=text("",13);caption.setMaxLines(2);left.addView(caption,new LinearLayout.LayoutParams(-1,dp(40)));resolution=button("resolution","",host::resolution);left.addView(resolution,new LinearLayout.LayoutParams(-1,dp(60)));full=button("full_preview","Ver a pantalla completa",()->{if(!previewId.isEmpty())host.fullPreview(previewId);});full.setEnabled(false);full.setAlpha(.45f);LinearLayout.LayoutParams fullParams=new LinearLayout.LayoutParams(-1,dp(38));fullParams.topMargin=dp(7);left.addView(full,fullParams);
  LinearLayout right=new LinearLayout(activity);right.setOrientation(1);body.addView(right,new LinearLayout.LayoutParams(0,-1,6));String[] modes={"original","photo","slideshow","daily"};for(int row=0;row<2;row++){LinearLayout line=new LinearLayout(activity);right.addView(line,new LinearLayout.LayoutParams(-1,dp(78)));for(int col=0;col<2;col++){String mode=modes[row*2+col];LinearLayout tile=new LinearLayout(activity);tile.setOrientation(1);tile.setPadding(dp(12),dp(9),dp(12),dp(6));style(tile);tile.setClickable(true);TextView name=text(modeName(mode),17);name.setTextColor(Color.WHITE);tile.addView(name);TextView desc=text("",12);desc.setMaxLines(2);tile.addView(desc);descriptions.put(mode,desc);actions.put("mode:"+mode,tile);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(dp(3),dp(3),dp(3),dp(3));line.addView(tile,p);tile.setOnFocusChangeListener((v,f)->{if(f){lastFocus="mode:"+mode;focusMode(mode);}});tile.setOnClickListener(v->host.activate(mode));}}
  TextView section=text("Opciones del fondo",13);section.setPadding(dp(3),dp(7),0,dp(3));right.addView(section,new LinearLayout.LayoutParams(-1,dp(29)));contextDescription=text("",12);contextDescription.setPadding(dp(3),0,dp(3),0);right.addView(contextDescription,new LinearLayout.LayoutParams(-1,dp(25)));for(int i=0;i<3;i++){final int index=i;Button b=button("context:"+i,"",()->{Runnable run=contextActions.get("context:"+index);if(run!=null)run.run();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(43));p.setMargins(dp(3),0,dp(3),dp(5));right.addView(b,p);contextual.add(b);}
  LinearLayout footer=new LinearLayout(activity);LinearLayout.LayoutParams foot=new LinearLayout.LayoutParams(-1,dp(43));foot.topMargin=dp(8);root.addView(footer,foot);String[] ids={"receive","import","library","home","back"},labels={"Desde el celular","Desde TV o USB","Mis fotos","Ver inicio","Volver"};Runnable[] runs={host::receive,host::importFiles,host::library,host::home,host::back};for(int i=0;i<ids.length;i++){Button b=button(ids[i],labels[i],runs[i]);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(dp(3),0,dp(3),0);footer.addView(b,p);}activity.setContentView(root);update();View focus=actions.get(lastFocus);if(focus==null)focus=actions.get("mode:"+focusedMode);if(focus!=null)focus.requestFocus();loadData(token);
 }
 boolean visible(){return visible;}
 void save(Bundle b){b.putString("overview.mode",focusedMode);b.putString("overview.focus",lastFocus);}
 void restore(Bundle b){focusedMode=b.getString("overview.mode",focusedMode);lastFocus=b.getString("overview.focus",lastFocus);}
 void trim(){previewToken++;if(image!=null)image.setImageDrawable(null);if(bitmap!=null){bitmap.recycle();bitmap=null;}previewKey="";if(visible)schedulePreview();}
 void focusMode(String mode){if(!Arrays.asList("original","photo","slideshow","daily").contains(mode))return;focusedMode=mode;updateContext();schedulePreview();}
 void focusApplied(){focusedMode=prefs.getString("wallpaper_mode","original");lastFocus="mode:"+focusedMode;}
 void refresh(){if(visible){update();loadData(epoch);}}
 void dailyBusy(boolean value){dailyBusy=value;updateContext();}
 private void loadData(int token){try{worker.execute(()->{boolean exists=WallpaperOnline.file(activity)!=null,today=exists&&WallpaperOnline.today().equals(prefs.getString("wallpaper_daily_date",""));List<WallpaperStore.Photo> list;try{list=store.photos();}catch(Exception e){ui.post(()->{if(visible&&token==epoch)status.setText("No se pudo leer Mis fotos");});return;}ui.post(()->{if(!visible||token!=epoch)return;photos=list;dailyExists=exists;dailyToday=today;dataReady=true;update();});});}catch(RejectedExecutionException ignored){}}
 private void update(){if(!visible)return;String mode=prefs.getString("wallpaper_mode","original");activeLabel.setText("En uso: "+modeName(mode));for(String key:descriptions.keySet()){String description=key.equals("original")?"Color de Z6, sin fotos":key.equals("photo")?"La última foto elegida":key.equals("slideshow")?(dataReady?WallpaperSelection.summary(prefs,photos):"Cargando fotos…"):"De Internet · Wikimedia";descriptions.get(key).setText((mode.equals(key)?"✓ En uso · ":"")+description);}Button library=(Button)actions.get("library");library.setText(dataReady?"Mis fotos ("+photos.size()+")":"Mis fotos…");int cap=WallpaperImages.usable(activity,prefs.getString("wallpaper_quality","auto"));String value=WallpaperImages.label(cap>=3840?"ultra":cap>=1920?"balanced":"light");String q=prefs.getString("wallpaper_quality","auto");resolution.setText("Resolución del fondo\n"+(q.equals("auto")?"Automática · hasta ":"Hasta ")+value+" para este inicio");updateContext();schedulePreview();}
 private void context(int index,String label,Runnable run){Button b=contextual.get(index);if(!b.getText().toString().equals(label))b.setText(label);if(b.getVisibility()!=View.VISIBLE)b.setVisibility(View.VISIBLE);b.setEnabled(true);b.setAlpha(1);contextActions.put("context:"+index,run);}
 private void updateContext(){if(!visible||contextual.isEmpty())return;for(int i=0;i<contextual.size();i++){Button b=contextual.get(i);boolean show=focusedMode.equals("slideshow")||focusedMode.equals("daily")&&(i==0||i==1&&dailyExists);int visibility=show?View.VISIBLE:View.INVISIBLE;if(b.getVisibility()!=visibility)b.setVisibility(visibility);}contextActions.clear();String detail=focusedMode.equals("original")?"Sin imágenes ni descargas":focusedMode.equals("photo")?"Cambia la foto desde Mis fotos":"";if(!contextDescription.getText().toString().equals(detail))contextDescription.setText(detail);if(focusedMode.equals("original")){}
  else if(focusedMode.equals("photo")){}
  else if(focusedMode.equals("slideshow")){context(0,"Fotos: "+WallpaperSelection.summary(prefs,photos),host::selection);Button interval=contextual.get(1);context(1,"Cambiar cada "+prefs.getInt("wallpaper_minutes",30)+" min · ← →",()->{});interval.setOnKeyListener((v,key,e)->{if(e.getAction()!=KeyEvent.ACTION_DOWN||!focusedMode.equals("slideshow")||(key!=KeyEvent.KEYCODE_DPAD_LEFT&&key!=KeyEvent.KEYCODE_DPAD_RIGHT))return false;int[] values={5,15,30,60};int at=0,current=prefs.getInt("wallpaper_minutes",30);for(int i=0;i<values.length;i++)if(values[i]==current)at=i;int next=Math.max(0,Math.min(3,at+(key==KeyEvent.KEYCODE_DPAD_RIGHT?1:-1)));prefs.edit().putInt("wallpaper_minutes",values[next]).apply();interval.setText("Cambiar cada "+values[next]+" min · ← →");return true;});context(2,"Ordenar las fotos participantes",host::order);}
  else{boolean exists=dailyExists,today=dailyToday;String label=dailyBusy?"Descargando…":today?"Actualizado hoy":exists?"Último paisaje guardado · actualizar":"Descargar paisaje de hoy";context(0,label,host::updateDaily);contextual.get(0).setEnabled(!dailyBusy&&!today);contextual.get(0).setAlpha(dailyBusy||today?.55f:1);if(exists)context(1,"Créditos: autor y licencia",host::credits);}
 }
 private void schedulePreview(){if(pendingFocus!=null)ui.removeCallbacks(pendingFocus);final int token=++previewToken;pendingFocus=()->loadPreview(token);ui.postDelayed(pendingFocus,260);}
 private void loadPreview(int token){final int previewWidth=imageFrame.getWidth()>0?Math.min(960,imageFrame.getWidth()):960,previewHeight=imageFrame.getHeight()>0?Math.min(540,imageFrame.getHeight()):540;final String mode=focusedMode;final List<WallpaperStore.Photo> snapshot=photos;final int viewEpoch=epoch;if(queuedPreview!=null)worker.remove(queuedPreview);queuedPreview=()->{File file=null;String id="",title=modeName(mode);boolean contain=false;try{if(mode.equals("daily")){file=WallpaperOnline.file(activity);id=file==null?"":"daily";}else if(mode.equals("photo")){String chosen=prefs.getString("wallpaper_photo","");for(WallpaperStore.Photo p:snapshot)if(p.id.equals(chosen)){file=p.file;id=p.id;contain=p.fit.equals("contain");}}else if(mode.equals("slideshow")){List<WallpaperStore.Photo> eligible=WallpaperSelection.eligible(prefs,snapshot);if(!eligible.isEmpty()){WallpaperStore.Photo p=eligible.get(0);file=p.file;id=p.id;contain=p.fit.equals("contain");}}String signature=file==null?mode+"|empty":file.getPath()+"|"+file.lastModified();if(file==null){final String label="Vista previa: "+title+(mode.equals("original")?"":" · elige o añade una imagen");ui.post(()->{if(!visible||token!=previewToken||viewEpoch!=epoch)return;image.setVisibility(View.INVISIBLE);shade.setVisibility(View.GONE);caption.setText(label);previewId="";full.setEnabled(false);full.setAlpha(.45f);});return;}if(signature.equals(previewKey)&&bitmap!=null&&!bitmap.isRecycled()){final String label="Vista previa: "+title,target=id;ui.post(()->{if(!visible||token!=previewToken||viewEpoch!=epoch)return;image.setVisibility(View.VISIBLE);shade.setVisibility(View.VISIBLE);caption.setText(label);previewId=target;full.setEnabled(true);full.setAlpha(1);});return;}Bitmap fresh=file==null?null:WallpaperImages.frame(file,previewWidth,previewHeight);final String target=id,key=signature;final Bitmap ready=fresh;final boolean fit=contain||fresh!=null&&fresh.getWidth()<=fresh.getHeight();final String label="Vista previa: "+title+(file==null&&!mode.equals("original")?" · elige o añade una imagen":"");ui.post(()->{if(!visible||token!=previewToken||viewEpoch!=epoch){if(ready!=null)ready.recycle();return;}image.setImageDrawable(null);if(bitmap!=null)bitmap.recycle();bitmap=ready;previewId=target;previewKey=key;image.setBackgroundColor(ready==null?Color.TRANSPARENT:WallpaperImages.DARK);image.setScaleType(fit?ImageView.ScaleType.FIT_CENTER:ImageView.ScaleType.CENTER_CROP);image.setImageBitmap(ready);image.setVisibility(View.VISIBLE);shade.setVisibility(ready==null?View.GONE:View.VISIBLE);caption.setText(label);full.setEnabled(ready!=null);full.setAlpha(ready==null?.45f:1);});}catch(Exception e){ui.post(()->{if(visible&&token==previewToken){caption.setText("No se pudo mostrar esta imagen");full.setEnabled(false);}});}};try{worker.execute(queuedPreview);}catch(RejectedExecutionException ignored){}}
 void hide(){visible=false;epoch++;previewToken++;ui.removeCallbacksAndMessages(null);worker.getQueue().clear();if(image!=null)image.setImageDrawable(null);if(bitmap!=null){bitmap.recycle();bitmap=null;}previewKey="";previewId="";}
 void destroy(){hide();worker.shutdownNow();}
 JSONObject inspect()throws JSONException{JSONObject out=new JSONObject().put("dailyBusy",dailyBusy).put("focusedMode",focusedMode).put("appliedMode",prefs.getString("wallpaper_mode","original")).put("previewId",previewId).put("previewBytes",bitmap==null?0:bitmap.getAllocationByteCount()).put("previewWidth",bitmap==null?0:bitmap.getWidth()).put("previewHeight",bitmap==null?0:bitmap.getHeight());JSONArray a=new JSONArray();for(Map.Entry<String,View> entry:actions.entrySet()){View v=entry.getValue();int[] position=new int[2];v.getLocationOnScreen(position);a.put(new JSONObject().put("id",entry.getKey()).put("visible",v.getVisibility()==View.VISIBLE).put("enabled",v.isEnabled()).put("focused",v.hasFocus()).put("x",position[0]).put("y",position[1]).put("width",v.getWidth()).put("height",v.getHeight()));}out.put("actions",a);return out;}
 String action(String id){View view=actions.get(id);if(!visible||view==null)return "NOT_FOUND";if(!view.isEnabled()||view.getVisibility()!=View.VISIBLE)return "DISABLED";view.performClick();return "OK";}
 String focus(String id){View view=actions.get(id);return visible&&view!=null&&view.getVisibility()==View.VISIBLE&&view.requestFocus()?"OK":"NOT_FOUND";}
